import {LitElement,html} from '/Users/peterkloss/Dev/ACMElabs/design-system/node_modules/lit';
import {ActionSubmitter} from '/Users/peterkloss/Dev/ACMElabs/design-system/src/shared/action-submitter';
class ActionProbe extends LitElement {
 static observedAttributes=['type','name','value','disabled','form','formaction','formmethod','formenctype','formnovalidate','formtarget'];
 private readonly submitter=new ActionSubmitter(this,()=>({type:(this.getAttribute('type')??'button') as 'button'|'submit'|'reset',disabled:this.hasAttribute('disabled'),link:false,name:this.getAttribute('name')??'',value:this.getAttribute('value')??'',formAction:this.getAttribute('formaction')??undefined,formMethod:this.getAttribute('formmethod')??undefined,formEnctype:this.getAttribute('formenctype')??undefined,formTarget:this.getAttribute('formtarget')??undefined,formNoValidate:this.hasAttribute('formnovalidate')}),()=>this.sync());
 get proxy(){return this.submitter.element;}
 get surface(){return this.shadowRoot?.querySelector('button')!;}
 attributeChangedCallback(){this.sync();this.requestUpdate();}
 sync(){this.submitter?.sync();const control=this.surface;if(control){control.type=this.proxy.type;control.disabled=this.submitter.disabled.get();}}
 protected updated(){this.sync();}
 click(){this.sync();if(!this.submitter.disabled.get())this.surface?.click();}
 render(){return html`<form @submit=${(event:Event)=>this.submitter.activate(event)} @reset=${(event:Event)=>this.submitter.activate(event)}><button type=${this.getAttribute('type')??'button'}><slot></slot></button></form>`;}
}
customElements.define('action-probe',ActionProbe);
const results:any[]=[];const check=(name:string,ok:boolean,actual?:unknown)=>results.push({name,ok,...(!ok?{actual}:{})});
try{
 const form=document.createElement('form');form.id='owner';form.innerHTML='<input name="text" value="one" required><input name="second" value="two"><action-probe type="submit" name="action" value="save">Save</action-probe>';document.body.append(form);const button=form.querySelector('action-probe') as ActionProbe;await button.updateComplete;let submits=0,last:HTMLButtonElement|undefined,data:FormData|undefined;form.addEventListener('submit',event=>{event.preventDefault();submits++;last=event.submitter as HTMLButtonElement;data=new FormData(form,last);});
 button.click();check('native shadow default action submits with real name/value',submits===1&&data?.get('action')==='save'&&last===button.proxy,{submits,owner:button.proxy.form?.id,proxyType:button.proxy.type,innerType:button.surface.type,children:button.innerHTML,innerOwner:button.surface.form?.outerHTML,data:data?[...data]:null});
 check('submitter remains associated after dispatch',last?.form===form&&new FormData(form,last).get('action')==='save');
 check('native named collection contains one submitter',form.elements.namedItem('action')===button.proxy);
 const cancel=(event:Event)=>{event.stopPropagation();event.preventDefault();};button.addEventListener('click',cancel);button.click();check('stopped and canceled click has no submit',submits===1);button.removeEventListener('click',cancel);
 const cancelAncestor=(event:Event)=>event.preventDefault();document.body.addEventListener('click',cancelAncestor);button.click();check('ancestor cancellation reaches the native default action',submits===1);document.body.removeEventListener('click',cancelAncestor);
 button.setAttribute('value','publish');button.setAttribute('formaction','/publish');button.setAttribute('formmethod','post');button.setAttribute('formenctype','text/plain');button.setAttribute('formtarget','result');button.click();check('latest values and native overrides survive submission',submits===2&&data?.get('action')==='publish'&&last?.getAttribute('formaction')==='/publish'&&last?.formMethod==='post'&&last?.formEnctype==='text/plain'&&last?.formTarget==='result');
 const input=form.querySelector('input')!;input.value='';button.click();check('native constraint validation blocks submission',submits===2);button.setAttribute('formnovalidate','');button.click();check('submitter novalidate override is native',submits===3);
 input.value='changed';button.setAttribute('type','reset');button.click();check('reset uses the outer form native reset',input.value==='one');
 const external=document.createElement('action-probe') as ActionProbe;external.setAttribute('form','owner');external.setAttribute('type','submit');external.setAttribute('name','external');external.setAttribute('value','yes');external.textContent='External';document.body.append(external);await external.updateComplete;external.click();check('external form association works',submits===4&&data?.get('external')==='yes');
 const fieldset=document.createElement('fieldset');fieldset.disabled=true;fieldset.innerHTML='<legend>Allowed</legend>';form.append(fieldset);fieldset.append(button);button.setAttribute('type','submit');button.click();check('disabled Fieldset blocks before a render',submits===4);fieldset.querySelector('legend')!.append(button);button.click();check('first legend preserves native Fieldset exception',submits===5);
 form.insertBefore(button,form.firstChild);button.id='primary';input.value='ready';button.setAttribute('value','implicit');
 (window as any).__submits=()=>submits;(window as any).__data=()=>data?.get('action');(window as any).__button=button;(window as any).__results={results};
}catch(error){(window as any).__results={results,error:String(error),stack:(error as Error).stack}}

