try{for(const engine of ["chromium","firefox","webkit"]){const browser=await pw[engine].launch(engine==="chromium"?{headless:true,executablePath:"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"}:{headless:true});try{const page=await browser.newPage();page.on("pageerror",error=>report.errors.push({engine,message:error.message}));await page.goto(server.url.href);await page.waitForFunction(()=>window.__results);const data=await page.evaluate(()=>window.__results);if(!data.error){const before=await page.evaluate(()=>window.__submits());await page.locator("input[name=text]").focus();await page.keyboard.press("Enter");const after=await page.evaluate(()=>({count:window.__submits(),value:window.__data()}));data.results.push({name:"implicit Enter uses the native submitter",ok:after.count===before+1&&after.value==="implicit",actual:after});}if(data.error)report.errors.push({engine,message:data.error});report.engines.push({engine,version:browser.version(),...data});console.log({engine,passed:data.results.filter(v=>v.ok).length,total:data.results.length,failed:data.results.filter(v=>!v.ok)});}finally{await browser.close();}}}finally{server.stop(true);}
await Bun.write(directory+"/results.json",JSON.stringify(report,null,2)+"\n");
if(report.errors.length||report.engines.some(r=>r.results.length!==13||r.results.some(v=>!v.ok)))process.exitCode=1;

